package topo

import "testing"

func TestSimple(t *testing.T) {
	g := map[string][]string{
		"A": {"B", "C"},
		"B": {"D"},
		"C": {"D"},
		"D": {},
	}
	order, err := TopoSort(g)
	if err != nil { t.Fatalf("unexpected error: %v", err) }
	pos := map[string]int{}
	for i, v := range order { pos[v] = i }
	if pos["A"] >= pos["B"] || pos["A"] >= pos["C"] { t.Fatal("A must come before B and C") }
	if pos["B"] >= pos["D"] || pos["C"] >= pos["D"] { t.Fatal("B and C must come before D") }
}

func TestSingleNode(t *testing.T) {
	g := map[string][]string{"X": {}}
	order, err := TopoSort(g)
	if err != nil { t.Fatalf("unexpected error: %v", err) }
	if len(order) != 1 || order[0] != "X" { t.Fatalf("want [X], got %v", order) }
}

func TestCycleDetected(t *testing.T) {
	g := map[string][]string{
		"A": {"B"},
		"B": {"C"},
		"C": {"A"},
	}
	_, err := TopoSort(g)
	if err == nil { t.Fatal("expected cycle error, got nil") }
}

func TestLinearChain(t *testing.T) {
	g := map[string][]string{"1": {"2"}, "2": {"3"}, "3": {}}
	order, err := TopoSort(g)
	if err != nil { t.Fatalf("unexpected error: %v", err) }
	if order[0] != "1" || order[1] != "2" || order[2] != "3" {
		t.Fatalf("want [1 2 3], got %v", order)
	}
}
